/* Reproduce Classroom — local-first demonstrator. No uploaded code is executed. */
const STORAGE_KEY = 'reproduce-classroom-v1';
const TYPES = ['AI互动网页', 'Micro:bit', 'ESP32', 'Arduino', '机器人', 'STEAM / 本土文化'];
const SUBJECTS = ['科学', '信息科技', 'STEAM', '创客与机器人', '综合实践'];
const DIFFICULTIES = ['入门', '中等', '较高'];
const VALIDATION = { unverified: '尚未验证', author_verified: '作者已验证', others_reproduced: '他人已复现' };
const TEACHING_VALIDATION = { not_used: '尚未课堂实施', author_classroom: '作者课堂实施', multi_teacher_classroom: '多教师课堂实施' };
const AIProvider = { name:'Mock Provider', extractFromText(text){const source=String(text||'');return { subject:SUBJECTS.find(x=>source.includes(x))||'', type:TYPES.find(x=>source.includes(x))||'', hasVersion:/\b\d+(?:\.\d+)?\b/.test(source), notes:'Mock 仅演示信息检查；输出必须由教师确认，不能直接发布。' } } };
const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c]));
const slugify = value => `${value || 'project'}`.trim().toLowerCase().replace(/[^\w\u4e00-\u9fff]+/g, '-').replace(/^-|-$/g, '') || `project-${Date.now()}`;
const uid = prefix => `${prefix}_${Date.now().toString(36)}${Math.random().toString(36).slice(2,6)}`;
const now = () => new Date().toISOString();

const seedSteps = (kind, hardware = false) => [
  { title: hardware ? '准备设备' : '准备材料与账户', description: hardware ? `确认 ${kind} 所需设备、数据线和电源均可用。` : '准备项目素材，并确认可使用所需网站或工具。', reason: '先确认基础条件，避免课堂中断。', expectedResult: '所需物品和账号均已准备。', troubleshooting: '先按项目清单逐项检查；硬件项目请使用支持数据传输的数据线。', estimatedTime: '15 分钟' },
  { title: '准备软件环境', description: '安装或打开项目指定的软件，确认版本与浏览器兼容。', reason: '明确环境差异，才能让其他教师稳定复现。', expectedResult: '能打开项目工具并看到示例内容。', troubleshooting: '检查网络、软件版本和学校设备权限。', estimatedTime: '20 分钟' },
  { title: '获取并运行示例', description: '使用项目提供的资源或预制代码运行最小示例。', reason: '先验证最小可运行状态，再增加教学任务。', expectedResult: '出现预期的示例结果。', troubleshooting: '回到上一步检查配置，不要同时修改多个变量。', estimatedTime: '20 分钟' },
  { title: '检查结果并进入教学', description: '按照成功标准测试，并把操作转换为学生可以完成的任务。', reason: '技术运行不是终点，教学目标才是终点。', expectedResult: '能解释一个结果，并完成一项教学活动。', troubleshooting: '先使用项目提供的样例数据或简化任务。', estimatedTime: '25 分钟' }
];

function project({ id, title, type, subject, grade, cover, glyph, summary, hardware, lessons, difficulty, goal, needs, validation, teachingValidation, ai = 'assisted', author = '示例团队', sourceType = 'original', steps, decisions, audience, software, hardwareItems }) {
  return { id, slug: slugify(title), title, subtitle: '示例项目 / Demo', type, subject, grade, cover, glyph, summary, description: summary, hardware, lessons, difficulty, goal, needs, validation, teachingValidation, ai, author, sourceType, originalSourceUrl: '', license: '示例资料，不可作为真实来源', status: 'published', createdAt: '2026-08-10', updatedAt: '2026-08-26', lastVerifiedAt: '2026-08-24', viewCount: 0, reproductionCount: 0, teamId: 'team_demo', authorId: 'user_demo', audience: audience || { age: '10–12 岁', size: '4 人一组', priorKnowledge: '基础观察与记录', coding: '不要求', ai: '不要求', grouping: '小组协作' }, teacherRequirement: { subject, technicalLevel: difficulty, aiLevel: ai === 'none' ? '不要求' : '基础了解', preparationTime: '45–60 分钟' }, objectives: { subject: goal, technical: '能使用工具记录或处理信息', project: '在真实情境中提出并表达方案', aiLiteracy: ai === 'none' ? '本项目不以 AI 素养为核心目标' : '理解 AI 输出需要检查与验证', interdisciplinary: '将学科知识用于解决真实问题' }, hardwareItems: hardwareItems || (hardware ? [{ name: needs.split('、')[0], model: '请在真实项目中填写具体型号', quantity: 1, required: true, alternative: '查看项目替代方案' }] : []), software: software || [{ name: '浏览器 / 项目指定工具', version: '请在真实项目中填写版本', required: true, alternative: '使用学校允许的兼容浏览器' }], assets: [{ type: 'document', title: '项目说明（示例）', url: '#', version: 'Demo' }, { type: 'prompt', title: '教师准备提示（示例）', url: '#', version: 'Demo' }], steps: steps || seedSteps(type, hardware), decisions: decisions || [{ decision: '从最小可运行示例开始', reason: '降低教师第一次接触项目时的不确定性。', alternatives: '直接完成全部任务', whyNotAlternative: '难以定位失败原因。', canBeChanged: true, changeRisk: '一次增加太多变量会增加排错难度。' }], failures: [{ title: '环境版本不一致', stage: '准备软件环境', symptom: '教程中的界面与教师电脑不同', reason: '工具自动更新', solution: '记录版本并提供兼容说明', resolved: true, impact: '中等', advice: '真实发布前请补充版本号。' }], troubleshooting: [{ title: '项目无法启动', type: 'software', symptom: '页面或工具没有预期结果', cause: '环境、网络或资源路径不一致', solution: '回到软件环境步骤逐项确认。', step: 2, severity: 'medium' }] };
}

