function defaultState() {
  return { users:[{id:'user_demo',name:'林老师（示例）',email:'demo@reproduce.local',role:'admin',teamIds:['team_demo']}], teams:[{id:'team_demo',name:'示例创新小组',memberIds:['user_demo']}], projects:SEED_PROJECTS, attempts:[], adaptations:[], transfers:[], classrooms:[], relations:[], aiPackages:[], session:null, wizard:{}, ui:{detailTab:'reproduce',mode:'simple'} };
}
function readState(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY)) || defaultState()}catch{return defaultState()}}
let state = readState();
function save(){localStorage.setItem(STORAGE_KEY, JSON.stringify(state))}
function resetSeed(){state=defaultState();save();render();toast('已恢复示例数据。')}
function currentUser(){return state.users.find(u=>u.id===state.session) || null}
function go(path){location.hash = path.startsWith('#') ? path : `#${path}`}
function route(){return location.hash.replace(/^#/, '') || '/'}
function projectBySlug(slug){return state.projects.find(p=>p.slug===decodeURIComponent(slug))}
function requireUser(next){if(currentUser())return true;state.ui.returnTo=next || route();save();go('/login');toast('请先登录后继续。');return false}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),3000)}
function tag(text){return `<span class="tag">${esc(text)}</span>`}
function validationBadge(status){const css=status==='others_reproduced'?'success':status==='author_verified'?'neutral':'warning';return `<span class="badge ${css}">${VALIDATION[status]||esc(status)}</span>`}
function empty(message, action=''){return `<div class="empty"><p>${esc(message)}</p>${action}</div>`}

function header(){const user=currentUser();const r=route();document.getElementById('siteHeader').innerHTML=`<a class="brand" href="#/"><span class="brand-mark">↗</span><span>复现课堂</span></a><nav class="main-nav" aria-label="主导航"><a class="${r==='/'?'active':''}" href="#/">首页</a><a class="${r.startsWith('/projects')?'active':''}" href="#/projects">发现项目</a><a href="#/projects/new">上传项目</a><a class="${r.startsWith('/me')?'active':''}" href="#/me/projects">我的实践</a></nav><div class="header-actions">${user?`<button data-action="logout">退出</button><button class="avatar" data-action="profile" aria-label="个人中心">${esc(user.name.slice(0,1))}</button>`:`<a class="button button-secondary" href="#/login">登录 / 注册</a>`}</div>`;document.getElementById('siteFooter').innerHTML=`<a class="brand" href="#/"><span class="brand-mark">↗</span><span>复现课堂</span></a><p>帮助教师把优秀教学实践，逐渐变成自己的真实教学实践。</p><span>本地演示 · 数据仅保存在当前浏览器</span>`}

function projectReadiness(p){let score=0;if(p.summary)score+=15;if(p.steps&&p.steps.length>=3)score+=35;if((p.hardwareItems&&p.hardwareItems.length)||!p.hardware)score+=15;if(p.software&&p.software.length)score+=15;if(p.decisions&&p.decisions.length)score+=10;if(p.troubleshooting&&p.troubleshooting.length)score+=10;return Math.min(score,100)}
function projectCard(p){const readiness=projectReadiness(p);return `<article class="project-card" tabindex="0" data-go="/projects/${encodeURIComponent(p.slug)}"><div class="project-cover cover-${p.cover||'green'}"><span class="cover-badge">${esc(p.type)}</span><span class="cover-glyph">${esc(p.glyph||'◌')}</span><span class="cover-action">查看复现路径 ↗</span><h3>${esc(p.title)}</h3></div><div class="project-body"><p class="project-summary">${esc(p.summary)}</p><div class="tags">${tag(`${p.subject} · ${p.grade}`)}${tag(p.lessons)}${tag(`教师 · ${p.difficulty}`)}${p.hardware?tag('需硬件'):tag('轻设备')}</div><div class="readiness"><span>信息准备度</span><i><b style="width:${readiness}%"></b></i><strong>${readiness}%</strong></div><div class="card-footer"><span><i class="dot"></i>${VALIDATION[p.validation]}</span><span>${p.lastVerifiedAt||'尚无验证'}</span></div></div></article>`}

function home(){const latest=state.projects.filter(p=>p.status==='published').slice(0,6);return `<div class="page"><section class="hero"><div class="hero-copy"><p class="eyebrow">TEACHING PRACTICE, MADE TRANSFERABLE</p><h1>把一个好项目，<br><em>真正变成你的课。</em></h1><p>找到教学实践，跟着完成复现，理解设计理由，再根据自己的学生、设备和课堂进行修改。</p><div class="actions"><a class="button button-primary" href="#/projects">探索项目 →</a><a class="button button-secondary" href="#/projects/new">上传项目</a></div><div class="hero-stats"><span><strong>—</strong>真实项目数据待积累</span><i></i><span><strong>${latest.length}</strong>个示例项目</span><i></i><span>不伪造验证统计</span></div></div><div class="hero-art"><div class="art-core">好项目<br>成为你的课</div><div class="art-pill">发现项目</div><div class="art-pill">跟着复现</div><div class="art-pill">调整迁移</div><div class="art-pill">进入课堂</div></div></section><section class="feature-strip"><div class="feature"><span class="feature-icon">◎</span><div><strong>看得懂</strong><p>设计理由不再隐身</p></div></div><div class="feature"><span class="feature-icon">↻</span><div><strong>做得出</strong><p>有步骤、标准和排错</p></div></div><div class="feature"><span class="feature-icon">⌁</span><div><strong>改得动</strong><p>结合自己的条件调整</p></div></div><div class="feature"><span class="feature-icon">✓</span><div><strong>有验证</strong><p>真实记录成为证据</p></div></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">START HERE</p><h2>从一个示例项目开始</h2></div><a class="text-link" href="#/projects">查看全部项目 →</a></div><div class="callout">这些均为示例项目 / Demo，用于说明信息结构；并非真实教师案例或验证数据。</div><div class="project-grid">${latest.map(projectCard).join('')}</div></section><section class="section workflow"><div class="workflow-copy"><p class="eyebrow">A REPRODUCTION PATH, NOT A DOWNLOAD</p><h2>不是下载一份资料，<br>而是走完一次实践。</h2><p>每个项目都把原作者脑中的隐性经验，拆成你可以判断、执行和修改的具体信息。</p></div><ol class="steps"><li><span class="number">01</span><div><h3>先判断适不适合</h3><p>学科、年级、设备与教师条件，一分钟看清。</p></div></li><li><span class="number">02</span><div><h3>跟着完成复现</h3><p>准备清单、分步指引、成功标准和排错都在同一处。</p></div></li><li><span class="number">03</span><div><h3>理解为什么这样设计</h3><p>看见核心决策，而不只是照着教程操作。</p></div></li><li><span class="number">04</span><div><h3>带着自己的条件修改</h3><p>将新版本和课堂反馈留给下一位教师。</p></div></li></ol></section></div>`}

function homeReworked(){const latest=state.projects.filter(p=>p.status==='published').slice(0,6);const featured=latest[0];const marks={'AI互动网页':'✦','Micro:bit':'⌁','ESP32':'◌','Arduino':'◒','机器人':'↗','STEAM / 本土文化':'◈'};return `<div class="page home-page"><section class="hero hero-reworked"><div class="hero-copy"><p class="eyebrow">TEACHING PRACTICE, MADE TRANSFERABLE</p><h1>把一个好项目，<br><em>真正变成你的课。</em></h1><p>不是收藏灵感，而是明确今天从哪里开始：准备什么、按哪一步做、哪里容易卡，以及怎样再变成自己的课堂。</p><div class="actions"><a class="button button-primary" href="#/projects">探索项目 →</a><a class="button button-secondary" href="#/projects/new">贡献一个项目</a></div><div class="hero-stats"><span><strong>—</strong>真实项目数据待积累</span><i></i><span><strong>${latest.length}</strong>个示例项目</span><i></i><span>不伪造验证统计</span></div></div><div class="hero-workbench"><div class="workbench-label">今天可以从这里开始</div><div class="workbench-card"><div class="workbench-icon">01</div><div><strong>选一个“条件接近”的项目</strong><p>按学科、年级、硬件与教师难度缩小范围。</p></div></div><div class="workbench-card"><div class="workbench-icon">02</div><div><strong>先跑通最小的第一步</strong><p>先准备，再运行；不把全部难题堆在同一节课。</p></div></div><div class="workbench-card is-accent"><div class="workbench-icon">03</div><div><strong>记录你和原项目的差异</strong><p>这会成为下一次改编的起点。</p></div></div><span class="workbench-sticker">先复现，<br>再创新</span></div></section><section class="feature-strip"><div class="feature"><span class="feature-icon">◎</span><div><strong>看得懂</strong><p>设计理由不再隐身</p></div></div><div class="feature"><span class="feature-icon">↻</span><div><strong>做得出</strong><p>有步骤、标准和排错</p></div></div><div class="feature"><span class="feature-icon">⌁</span><div><strong>改得动</strong><p>结合自己的条件调整</p></div></div><div class="feature"><span class="feature-icon">✓</span><div><strong>有验证</strong><p>真实记录成为证据</p></div></div></section><section class="section explore-types"><div class="section-heading"><div><p class="eyebrow">EXPLORE BY HOW YOU TEACH</p><h2>从你准备带的实践开始</h2></div><a class="text-link" href="#/projects">按更多条件筛选 →</a></div><div class="type-rail">${TYPES.map((type,i)=>`<a href="#/projects?type=${encodeURIComponent(type)}" class="type-tile type-${i%6}"><span>${marks[type]}</span><strong>${type}</strong><small>${type==='ESP32'||type==='Arduino'||type==='机器人'?'设备与环境':'教学任务与素材'}</small></a>`).join('')}</div></section><section class="featured-project"><div class="featured-copy"><p class="eyebrow">A GOOD PLACE TO START · DEMO</p><span class="featured-type">${esc(featured.type)} · ${esc(featured.subject)}</span><h2>${esc(featured.title)}</h2><p>${esc(featured.summary)}</p><div class="featured-facts"><span><b>${esc(featured.lessons)}</b>建议课时</span><span><b>${esc(featured.difficulty)}</b>教师难度</span><span><b>${featured.steps.length} 步</b>最小复现路径</span></div><a class="button button-primary" href="#/projects/${encodeURIComponent(featured.slug)}">查看项目路径 →</a></div><div class="featured-map"><p>复现地图</p>${featured.steps.map((s,i)=>`<div class="map-step"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(s.title)}</strong><small>${esc(s.estimatedTime)}</small></div>`).join('')}<div class="map-note">每一步都有<br>成功标准与排错</div></div></section><section class="section"><div class="section-heading"><div><p class="eyebrow">READY TO LOOK CLOSER</p><h2>为“真正开始”准备的项目</h2></div><a class="text-link" href="#/projects">查看全部项目 →</a></div><div class="callout">这些均为示例项目 / Demo，用于说明信息结构；信息准备度根据项目字段完整性计算，不代表真实复现成功率。</div><div class="project-grid">${latest.map(projectCard).join('')}</div></section><section class="section workflow"><div class="workflow-copy"><p class="eyebrow">A REPRODUCTION PATH, NOT A DOWNLOAD</p><h2>不是下载一份资料，<br>而是走完一次实践。</h2><p>每个项目都把原作者脑中的隐性经验，拆成你可以判断、执行和修改的具体信息。</p></div><ol class="steps"><li><span class="number">01</span><div><h3>先判断适不适合</h3><p>学科、年级、设备与教师条件，一分钟看清。</p></div></li><li><span class="number">02</span><div><h3>跟着完成复现</h3><p>准备清单、分步指引、成功标准和排错都在同一处。</p></div></li><li><span class="number">03</span><div><h3>理解为什么这样设计</h3><p>看见核心决策，而不只是照着教程操作。</p></div></li><li><span class="number">04</span><div><h3>带着自己的条件修改</h3><p>将新版本和课堂反馈留给下一位教师。</p></div></li></ol></section></div>`}

function projectsPage(){const params=new URLSearchParams(location.hash.split('?')[1]||'');const term=params.get('q')||'';const subject=params.get('subject')||'';const grade=params.get('grade')||'';const type=params.get('type')||'';const hardware=params.get('hardware')==='1';const difficulty=params.get('difficulty')||'';const sort=params.get('sort')||'updated';const grades=[...new Set(state.projects.map(p=>p.grade).filter(Boolean))];let items=state.projects.filter(p=>p.status==='published').filter(p=>!term||`${p.title} ${p.summary} ${p.subject}`.toLowerCase().includes(term.toLowerCase())).filter(p=>!subject||p.subject===subject).filter(p=>!grade||p.grade===grade).filter(p=>!type||p.type===type).filter(p=>!difficulty||p.difficulty===difficulty).filter(p=>!hardware||p.hardware);items.sort((a,b)=>sort==='verified'?String(b.lastVerifiedAt).localeCompare(String(a.lastVerifiedAt)):sort==='reproductions'?(b.reproductionCount||0)-(a.reproductionCount||0):String(b.updatedAt).localeCompare(String(a.updatedAt)));return `<div class="page"><div class="page-title"><p class="eyebrow">DISCOVER PROJECTS</p><h1>发现可复现的教学实践</h1><p>通过条件、验证状态和完整步骤，而不是热度，判断一个项目是否适合你。</p></div><form class="toolbar" data-form="project-filters"><input class="search" name="q" placeholder="搜索项目、学科或关键词" value="${esc(term)}"><select class="select" name="subject"><option value="">全部学科</option>${SUBJECTS.map(x=>`<option ${x===subject?'selected':''}>${x}</option>`).join('')}</select><select class="select" name="grade"><option value="">全部年级</option>${grades.map(x=>`<option ${x===grade?'selected':''}>${x}</option>`).join('')}</select><select class="select" name="type"><option value="">全部类型</option>${TYPES.map(x=>`<option ${x===type?'selected':''}>${x}</option>`).join('')}</select><select class="select" name="difficulty"><option value="">教师难度</option>${DIFFICULTIES.map(x=>`<option ${x===difficulty?'selected':''}>${x}</option>`).join('')}</select><select class="select" name="sort"><option value="updated" ${sort==='updated'?'selected':''}>最近更新</option><option value="verified" ${sort==='verified'?'selected':''}>最近验证</option><option value="reproductions" ${sort==='reproductions'?'selected':''}>复现次数</option></select><label class="tag"><input type="checkbox" name="hardware" ${hardware?'checked':''}> 需要硬件</label><button class="button button-primary">筛选</button></form>${items.length?`<div class="project-grid">${items.map(projectCard).join('')}</div>`:empty('没有匹配的项目。请调整筛选条件，或创建一个项目。','<a class="button button-secondary" href="#/projects/new">创建项目</a>')}</div>`}

function credibility(p){return `<div class="panel"><h2>项目可信度</h2><div class="quick-grid"><div class="quick-item"><p>来源</p><strong>${p.sourceType==='original'?'原创':p.sourceType==='adapted'?'改编':'外部引用'}</strong></div><div class="quick-item"><p>AI 参与</p><strong>${p.ai==='heavy'?'大量 AI 辅助':p.ai==='assisted'?'AI 辅助':'无明显 AI 参与'}</strong></div><div class="quick-item"><p>技术验证</p><strong>${VALIDATION[p.validation]}</strong></div><div class="quick-item"><p>教学验证</p><strong>${TEACHING_VALIDATION[p.teachingValidation]}</strong></div><div class="quick-item"><p>最后验证</p><strong>${p.lastVerifiedAt||'暂无数据'}</strong></div><div class="quick-item"><p>项目来源</p><strong>${p.author}</strong></div></div></div>`}
function projectDetail(p){const tab=state.ui.detailTab||'reproduce';const quick=[['教学对象',`${p.grade} · ${p.audience.age}`],['建议课时',p.lessons],['教师难度',p.difficulty],['需要准备',p.needs],['核心目标',p.goal],['验证状态',VALIDATION[p.validation]]];let body='';if(tab==='reproduce')body=`<section class="panel"><h2>跟着复现</h2><p class="muted">每一步都明确做什么、为什么、成功是什么样，以及失败时如何处理。</p>${p.steps.map((s,i)=>`<article class="repro-step"><span>0${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="why-card"><strong>为什么这样做</strong>${esc(s.reason)}</div><div class="step-detail"><b>成功是：${esc(s.expectedResult)}</b><span>失败怎么办：${esc(s.troubleshooting)}</span></div></div></article>`).join('')}</section>`;if(tab==='understand')body=`<section class="panel"><h2>深入理解</h2><div class="notice">以下内容默认简化呈现。切换理解模式或完成理解检查前，不要求阅读全部技术细节。</div><h3>设计理由与关键决策</h3>${p.decisions.map(d=>`<div class="why-card"><strong>${esc(d.decision)}</strong><div>${esc(d.reason)}</div><p class="muted">替代方案：${esc(d.alternatives)}；未采用原因：${esc(d.whyNotAlternative)}；修改风险：${esc(d.changeRisk)}</p></div>`).join('')}<h3>常见失败</h3>${p.failures.map(f=>`<div class="repro-step"><span>!</span><div><h3>${esc(f.title)}</h3><p>${esc(f.symptom)} · ${esc(f.solution)}</p></div></div>`).join('')}<h3>资源与外部链接</h3><ul class="resource-list">${p.assets.map(a=>`<li><strong>${esc(a.title)}</strong> · ${esc(a.type)} <button class="text-link" data-action="external-link" data-url="${esc(a.url)}">查看资源</button></li>`).join('')}</ul></section>`;if(tab==='feedback')body=`<section class="panel"><h2>真实复现与课堂反馈</h2>${projectFeedback(p)}</section>`;return `<div class="page"><a class="text-link" href="#/projects">← 返回项目列表</a><section class="detail-hero"><p class="eyebrow">${esc(p.type)} · ${VALIDATION[p.validation]} · ${p.subtitle||''}</p><h1>${esc(p.title)}</h1><p>${esc(p.summary)}</p></section><div class="detail-layout"><div><section class="panel"><h2>一分钟判断：适合我吗？</h2><div class="quick-grid">${quick.map(([a,b])=>`<div class="quick-item"><p>${a}</p><strong>${esc(b)}</strong></div>`).join('')}</div></section><div class="detail-tabs"><button class="${tab==='reproduce'?'active':''}" data-action="detail-tab" data-tab="reproduce">跟着复现</button><button class="${tab==='understand'?'active':''}" data-action="detail-tab" data-tab="understand">深入理解</button><button class="${tab==='feedback'?'active':''}" data-action="detail-tab" data-tab="feedback">真实反馈</button></div>${body}${credibility(p)}</div><aside class="sticky-panel"><strong>准备好试一试了吗？</strong><p>先确认准备条件，再按步骤完成。过程中的卡点也很有价值。</p><button class="button button-primary" data-action="start-reproduction" data-project="${p.id}">我要复现 →</button><a class="button button-secondary" href="#/projects/${encodeURIComponent(p.slug)}/adapt">条件适配</a><a class="button button-secondary" href="#/projects/${encodeURIComponent(p.slug)}/learn">理解项目</a><a class="button button-secondary" href="#/projects/${encodeURIComponent(p.slug)}/develop-with-ai">AI 任务包</a><a class="button button-secondary" href="#/projects/${encodeURIComponent(p.slug)}/transfer">迁移学科</a></aside></div></div>`}
function projectFeedback(p){const attempts=state.attempts.filter(a=>a.projectId===p.id&&a.status==='completed');const classes=state.classrooms.filter(c=>c.projectId===p.id);if(!attempts.length&&!classes.length)return empty('尚未有真实复现或课堂反馈。示例项目不应假装有真实数据。','<a class="button button-secondary" href="#/projects/'+encodeURIComponent(p.slug)+'/classroom">记录一次课堂实施</a>');return `${attempts.map(a=>`<div class="classroom-card"><h3>${a.successLevel==='success'?'复现成功':a.successLevel==='partial'?'部分完成':'未完成'} · ${esc(a.userName||'匿名教师')}</h3><p>${esc(a.mainProblem||'未记录主要问题')}</p></div>`).join('')}${classes.map(c=>`<div class="classroom-card"><h3>课堂实施 · ${esc(c.classDate)}</h3><p>${esc(c.teacherReflection)}</p></div>`).join('')}`}

function loginPage(register=false){return `<div class="page"><div class="form-card" style="max-width:520px;margin:auto"><p class="eyebrow">LOCAL DEMO AUTH</p><h2>${register?'创建演示账户':'登录演示账户'}</h2><p class="form-hint">这是本地 Mock 认证，不发送邮件、不连接真实账号服务。真实认证需接入 Supabase 或等效服务。</p><form data-form="${register?'register':'login'}"><div class="field"><label>姓名</label><input ${register?'required':''} name="name" value="${register?'':'林老师（示例）'}" ${register?'':'readonly'}></div><div class="field"><label>邮箱</label><input required type="email" name="email" value="${register?'':'demo@reproduce.local'}"></div>${register?'<div class="field"><label>团队名称（可选）</label><input name="team" placeholder="例如：学校创客组"></div>':''}<button class="button button-primary" type="submit">${register?'注册并继续':'登录'} →</button></form><p class="muted" style="margin-top:15px">${register?'已有演示账户？ <a href="#/login">登录</a>':'没有账户？ <a href="#/register">创建本地演示账户</a>'}</p></div></div>`}

const WIZARD_STEPS=['基本信息','教学对象','教师要求','教学目标','硬件','软件','资源','复现步骤','设计理由','失败经验','预览','发布'];
function newProjectPage(editProject){if(!requireUser('/projects/new'))return '';let draft=editProject||state.wizard;const step=Math.max(0,Math.min(Number(draft.step||0),WIZARD_STEPS.length-1));const base={title:'',summary:'',type:TYPES[0],subject:SUBJECTS[0],grade:'',lessons:'',difficulty:'入门',hardware:false,sourceType:'original',audience:{age:'',size:'',priorKnowledge:'',coding:'',ai:'',grouping:''},teacherRequirement:{technicalLevel:'入门',aiLevel:'不要求',preparationTime:''},objectives:{subject:'',technical:'',project:'',aiLiteracy:'',interdisciplinary:''},hardwareItems:[],software:[],assets:[],steps:[],decisions:[],failures:[]};draft={...base,...draft,audience:{...base.audience,...(draft.audience||{})},teacherRequirement:{...base.teacherRequirement,...(draft.teacherRequirement||{})},objectives:{...base.objectives,...(draft.objectives||{})}};state.wizard=draft;save();const content=wizardContent(draft,step);return `<div class="page"><div class="page-title"><p class="eyebrow">${editProject?'EDIT PROJECT':'CONTRIBUTE A PROJECT'}</p><h1>${editProject?'编辑项目':'上传一个可被别人跑通的项目'}</h1><p>先保存草稿也可以。发布前请确认复现所需的信息完整、无学生隐私信息。</p></div><div class="wizard"><nav class="wizard-nav">${WIZARD_STEPS.map((x,i)=>`<button data-action="wizard-step" data-step="${i}" class="${i===step?'active':''}">${String(i+1).padStart(2,'0')} ${x}</button>`).join('')}</nav><section class="form-card">${content}</section></div></div>`}
function field(name,label,value='',kind='text',full=false,options=[]){if(kind==='textarea')return `<div class="field ${full?'full':''}"><label>${label}</label><textarea name="${name}">${esc(value)}</textarea></div>`;if(kind==='select')return `<div class="field ${full?'full':''}"><label>${label}</label><select name="${name}">${options.map(x=>`<option value="${esc(x)}" ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`;return `<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${kind}" value="${esc(value)}"></div>`}
function wizardContent(d,s){const nav=`<div class="form-actions"><button class="button button-secondary" data-action="wizard-prev" ${s===0?'disabled':''}>← 上一步</button><div><button class="button button-secondary" data-action="save-draft">保存草稿</button>${s<10?'<button class="button button-primary" data-action="wizard-next">下一步 →</button>':''}</div></div>`;if(s===0)return `<h2>基本信息</h2><p class="form-hint">这不是营销描述；请写清它是什么、教学上解决什么。</p><div class="field-grid">${field('title','项目名称',d.title,'text',true)}${field('summary','项目简介',d.summary,'textarea',true)}${field('type','项目类型',d.type,'select',false,TYPES)}${field('subject','核心学科',d.subject,'select',false,SUBJECTS)}${field('grade','适用年级',d.grade)}${field('lessons','建议课时',d.lessons)}${field('difficulty','教师难度',d.difficulty,'select',false,DIFFICULTIES)}${field('sourceType','来源状态',d.sourceType,'select',false,['original','adapted','external'])}</div>${nav}`;
if(s===1)return `<h2>教学对象</h2><p class="form-hint">学生能做，与教师能带，是不同的条件。</p><div class="field-grid">${field('audience.age','学生年龄',d.audience.age)}${field('audience.size','学生人数 / 分组',d.audience.size)}${field('audience.priorKnowledge','前置知识',d.audience.priorKnowledge,'textarea',true)}${field('audience.coding','编程基础',d.audience.coding)}${field('audience.ai','AI 使用基础',d.audience.ai)}${field('audience.grouping','分组方式',d.audience.grouping)}</div>${nav}`;
if(s===2)return `<h2>教师要求</h2><div class="field-grid">${field('teacherRequirement.technicalLevel','需要的技术水平',d.teacherRequirement.technicalLevel,'select',false,DIFFICULTIES)}${field('teacherRequirement.aiLevel','需要的 AI 水平',d.teacherRequirement.aiLevel)}${field('teacherRequirement.preparationTime','预计准备时间',d.teacherRequirement.preparationTime)}${field('goal','一句话教学目标',d.goal,'textarea',true)}</div>${nav}`;
if(s===3)return `<h2>教学目标</h2><div class="field-grid">${field('objectives.subject','核心学科目标',d.objectives.subject,'textarea',true)}${field('objectives.technical','技术目标',d.objectives.technical,'textarea',true)}${field('objectives.project','项目目标',d.objectives.project,'textarea',true)}${field('objectives.aiLiteracy','AI 素养目标',d.objectives.aiLiteracy,'textarea',true)}${field('objectives.interdisciplinary','跨学科目标',d.objectives.interdisciplinary,'textarea',true)}</div>${nav}`;
if(s===4)return `<h2>硬件</h2><p class="form-hint">首版以文字清单记录；真实存储时应记录型号、数量、替代方案。</p><div class="field-grid">${field('needs','设备与材料清单',d.needs,'textarea',true)}${field('hardware','是否需要硬件（填写 是 / 否）',d.hardware?'是':'否')}</div>${nav}`;
if(s===5)return `<h2>软件与环境</h2><div class="field-grid">${field('softwareText','软件、版本、插件、账号和网络要求',d.softwareText||d.software.map(x=>`${x.name} ${x.version}`).join('\n'),'textarea',true)}</div>${nav}`;
if(s===6)return `<h2>项目资源</h2><div class="callout privacy">请勿上传学生姓名、学号、联系方式、可识别正脸、可识别语音或其他敏感身份信息。文件上传在演示版不可用，且上传代码绝不自动执行。</div><div class="field-grid">${field('assetsText','资源说明 / URL / GitHub / Prompt',d.assetsText||'','textarea',true)}</div>${nav}`;
if(s===7)return `<h2>复现步骤</h2><p class="form-hint">用「标题 | 做什么 | 为什么 | 成功表现 | 失败处理」每行一条填写。至少一条才可发布。</p>${field('stepsText','结构化步骤',d.stepsText||d.steps.map(x=>[x.title,x.description,x.reason,x.expectedResult,x.troubleshooting].join(' | ')).join('\n'),'textarea',true)}${nav}`;
if(s===8)return `<h2>设计理由</h2>${field('decisionsText','决策 | 为什么 | 可替代方案 | 修改风险',d.decisionsText||d.decisions.map(x=>[x.decision,x.reason,x.alternatives,x.changeRisk].join(' | ')).join('\n'),'textarea',true)}${nav}`;
if(s===9)return `<h2>失败经验（可选）</h2>${field('failuresText','问题 | 现象 | 原因 | 解决方案 | 给下一位教师的建议',d.failuresText||'','textarea',true)}${nav}`;
if(s===10)return `<h2>预览与信息完整度</h2>${missingInfo(d).length?`<div class="callout">发布前建议补充：${missingInfo(d).join('、')}。</div>`:'<div class="notice">基础信息完整，可以进入发布检查。</div>'}<div class="panel"><h2>${esc(d.title||'未命名项目')}</h2><p>${esc(d.summary||'尚未填写项目简介')}</p><div class="tags">${tag(d.subject)}${tag(d.grade||'未填年级')}${tag(d.type)}${tag(d.lessons||'未填课时')}</div><div class="actions"><button class="button button-secondary" data-action="mock-ai-check">用 Mock AI 检查缺失信息</button></div></div>${nav}`;
return `<h2>发布</h2><div class="callout privacy">发布确认：我确认未包含学生隐私信息；资源来源与版权状态已如实填写；AI 整理内容已由教师检查。</div><p class="form-hint">发布后其他演示用户可在本地项目列表中查看。真实生产环境需由服务端再次校验权限与资源安全。</p><div class="actions"><button class="button button-secondary" data-action="save-draft">保存草稿</button><button class="button button-primary" data-action="publish-project">确认发布</button></div>`}

function parseLines(text, keys){return String(text||'').split('\n').map(line=>line.trim()).filter(Boolean).map(line=>{const parts=line.split('|').map(x=>x.trim());return keys.reduce((obj,key,i)=>(obj[key]=parts[i]||'',obj),{})})}
function hydrateDraftFromForm(){const form=document.querySelector('.form-card');if(!form)return;const data=new FormData(form);for(const [key,value] of data.entries()){const parts=key.split('.');if(parts.length===1){if(key==='hardware')state.wizard.hardware=String(value).trim()==='是';else state.wizard[key]=String(value).trim()}else{if(!state.wizard[parts[0]])state.wizard[parts[0]]={};state.wizard[parts[0]][parts[1]]=String(value).trim()}}state.wizard.steps=parseLines(state.wizard.stepsText,['title','description','reason','expectedResult','troubleshooting']);state.wizard.decisions=parseLines(state.wizard.decisionsText,['decision','reason','alternatives','changeRisk']).map(x=>({...x,whyNotAlternative:'尚未填写',canBeChanged:true}));state.wizard.failures=parseLines(state.wizard.failuresText,['title','symptom','reason','solution','advice']).map(x=>({...x,stage:'复现过程',resolved:false,impact:'中等'}));state.wizard.software=String(state.wizard.softwareText||'').split('\n').filter(Boolean).map(line=>{const [name,version]=line.trim().split(/\s+/,2);return {name:name||'未命名软件',version:version||'未填写版本',required:true,alternative:'尚未填写'}});state.wizard.assets=String(state.wizard.assetsText||'').split('\n').filter(Boolean).map(line=>({type:'document',title:line,url:'#',version:'草稿'}));}
function missingInfo(d){const m=[];if(!d.title)m.push('项目名称');if(!d.summary)m.push('项目简介');if(!d.grade)m.push('适用年级');if(!d.lessons)m.push('建议课时');if(!d.goal&&!d.objectives?.subject)m.push('教学目标');if(!d.steps?.length)m.push('至少一个复现步骤');if(d.hardware&&!d.needs)m.push('硬件清单');return m}
function persistDraft(){hydrateDraftFromForm();state.wizard.status='draft';state.wizard.updatedAt=now();save();toast('草稿已保存在当前浏览器。')}
function publishWizard(){hydrateDraftFromForm();const missing=missingInfo(state.wizard);if(missing.length){toast(`暂不能发布：请补充${missing.join('、')}。`);return}const user=currentUser();const d=state.wizard;const existing=state.projects.find(p=>p.id===d.id);const record={...project({id:d.id||uid('project'),title:d.title,type:d.type,subject:d.subject,grade:d.grade,cover:d.cover||'green',glyph:'◌',summary:d.summary,hardware:!!d.hardware,lessons:d.lessons,difficulty:d.difficulty,goal:d.goal||d.objectives.subject,needs:d.needs||'请查看项目清单',validation:'unverified',teachingValidation:'not_used',ai:'none',author:user.name,sourceType:d.sourceType,steps:d.steps,decisions:d.decisions}),...d,id:d.id||uid('project'),slug:existing?.slug||`${slugify(d.title)}-${Date.now().toString(36).slice(-4)}`,status:'published',authorId:user.id,teamId:user.teamIds[0]||'',updatedAt:now(),publishedAt:now(),lastVerifiedAt:null,viewCount:0,reproductionCount:0};if(existing)Object.assign(existing,record);else state.projects.unshift(record);if(d.sourceProjectId&&!state.relations.some(r=>r.parentProjectId===d.sourceProjectId&&r.childProjectId===record.id))state.relations.push({id:uid('relation'),parentProjectId:d.sourceProjectId,childProjectId:record.id,relationType:'adaptation',createdBy:user.id,reason:'由条件适配或学科迁移草案创建',createdAt:now()});state.wizard={};save();toast('项目已发布。现在其他演示用户可以开始复现。');go(`/projects/${encodeURIComponent(record.slug)}`)}

function myProjects(){if(!requireUser('/me/projects'))return '';const user=currentUser();const items=state.projects.filter(p=>p.authorId===user.id);const teams=state.teams.filter(t=>user.teamIds.includes(t.id));return `<div class="page"><div class="page-title"><p class="eyebrow">MY PROJECTS</p><h1>我的项目</h1><p>项目可保存为草稿、发布或归档。每一次不完整的说明，都会影响下一位教师的复现。</p></div><div class="actions" style="margin:0 0 18px"><a class="button button-primary" href="#/projects/new">创建项目 →</a><a class="button button-secondary" href="#/me/reproductions">我的复现</a></div><section class="panel"><h2>我的团队</h2>${teams.length?teams.map(t=>`<div class="list-row"><div><h3>${esc(t.name)}</h3><p>${t.memberIds.length} 位成员</p></div></div>`).join(''):empty('尚未加入团队。')}<form data-form="team" class="toolbar" style="margin-top:12px"><input class="search" name="team" placeholder="输入团队名称以创建或加入"><button class="button button-secondary">创建 / 加入团队</button></form></section><section class="panel" style="margin-top:18px">${items.length?items.map(p=>`<div class="list-row"><div><h3>${esc(p.title)}</h3><p>${p.status==='draft'?'草稿':p.status==='archived'?'已归档':'已发布'} · ${esc(p.updatedAt?.slice(0,10)||'')}</p></div><div class="actions" style="margin:0"><a class="button button-secondary" href="#/projects/${encodeURIComponent(p.slug)}">查看</a><button class="button button-secondary" data-action="edit-project" data-project="${p.id}">编辑</button>${p.status==='published'?'<button class="button button-danger" data-action="archive-project" data-project="'+p.id+'">归档</button>':''}</div></div>`).join(''):empty('你还没有创建项目。','<a class="button button-primary" href="#/projects/new">创建第一份项目</a>')}</section></div>`}
function reproductionsPage(){if(!requireUser('/me/reproductions'))return '';const user=currentUser();const items=state.attempts.filter(a=>a.userId===user.id);return `<div class="page"><div class="page-title"><p class="eyebrow">MY REPRODUCTIONS</p><h1>我的复现</h1><p>复现记录既帮助你回到中断的位置，也帮助原作者补足信息。</p></div><div class="actions" style="margin:0 0 18px"><a class="button button-secondary" href="#/me/projects">我的项目</a><a class="button button-primary" href="#/projects">探索项目 →</a></div><section class="panel">${items.length?items.map(a=>{const p=state.projects.find(x=>x.id===a.projectId);return `<div class="list-row"><div><h3>${esc(p?.title||'项目已不存在')}</h3><p>${a.status==='completed'?'已完成':a.status==='abandoned'?'已放弃':'进行中'} · 当前第 ${a.currentStep+1||1} 步</p></div><a class="button button-secondary" href="#/reproductions/${a.id}">继续</a></div>`}).join(''):empty('尚未发起复现。','<a class="button button-primary" href="#/projects">从一个项目开始</a>')}</section></div>`}

function beginAttempt(projectId){if(!requireUser(`/projects/${projectBySlug(route().split('/')[2])?.slug||''}`))return;const user=currentUser();let attempt=state.attempts.find(a=>a.projectId===projectId&&a.userId===user.id&&a.status==='in_progress');if(!attempt){const p=state.projects.find(x=>x.id===projectId);attempt={id:uid('repro'),projectId,userId:user.id,teamId:user.teamIds[0]||'',userName:user.name,status:'in_progress',startedAt:now(),currentStep:0,successLevel:null,checklist:{},stepStates:(p.steps||[]).map(()=>({status:'not_started',note:''})),issues:[],reflection:{}};state.attempts.unshift(attempt);p.reproductionCount=(p.reproductionCount||0)+1;save()}go(`/reproductions/${attempt.id}`)}
function reproductionPage(attempt){const p=state.projects.find(x=>x.id===attempt.projectId);if(!p)return `<div class="page">${empty('找不到关联项目。')}</div>`;const groups=[['我已经有',p.hardwareItems.map(x=>x.name)],['我还缺',p.hardwareItems.filter(x=>x.required).map(x=>`${x.name}${x.model?' · '+x.model:''}`)],['我需要安装',p.software.filter(x=>x.required).map(x=>`${x.name} ${x.version}`)],['我需要下载',p.assets.filter(x=>x.type!=='prompt').map(x=>x.title)],['我需要学习',p.steps.slice(0,1).map(x=>x.title)]];return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">REPRODUCTION ATTEMPT</p><h1>${esc(p.title)}</h1><p>你的复现记录只保存在本地演示数据中。请真实记录卡点，而不是为了完成而标记成功。</p></div><div class="detail-layout"><div><section class="panel"><h2>开始前的准备清单</h2>${groups.map(([name,items])=>`<h3 style="font-size:13px;margin-top:16px">${name}</h3><ul class="checklist">${(items.length?items:['暂无项目数据']).map((x,i)=>`<li><input type="checkbox" data-action="toggle-check" data-key="${name}-${i}" ${attempt.checklist[`${name}-${i}`]?'checked':''}><span>${esc(x)}</span></li>`).join('')}</ul>`).join('')}</section><section class="panel" style="margin-top:18px"><h2>按步骤复现</h2><ol class="progress-list">${p.steps.map((s,i)=>{const ps=attempt.stepStates[i]||{status:'not_started'};return `<li><div class="progress-head"><strong>${i+1}. ${esc(s.title)}</strong><span class="badge ${ps.status==='completed'?'success':ps.status==='issue'?'warning':'neutral'}">${ps.status==='completed'?'完成':ps.status==='in_progress'?'进行中':ps.status==='issue'?'遇到问题':'未开始'}</span></div><p>${esc(s.description)}</p><div class="segmented">${[['not_started','未开始'],['in_progress','进行中'],['completed','完成'],['issue','遇到问题']].map(([v,l])=>`<button class="${ps.status===v?'selected':''}" data-action="step-status" data-index="${i}" data-status="${v}">${l}</button>`).join('')}</div>${ps.status==='issue'?`<div class="field" style="margin-top:9px"><label>我卡在哪里？</label><textarea data-issue-note="${i}" placeholder="描述现象、步骤和你已尝试的方法">${esc(ps.note||'')}</textarea><button class="text-link" data-action="save-issue" data-index="${i}">保存问题</button></div>`:''}</li>`}).join('')}</ol></section></div><aside class="sticky-panel"><strong>完成复现</strong><p>不要忽略部分完成和失败；这些是下一位教师的重要信息。</p><button class="button button-primary" data-action="finish-reproduction" data-attempt="${attempt.id}">提交结果与反思</button><p class="muted">当前状态：${attempt.status==='completed'?'已完成':'进行中'}</p></aside></div></div>`}
function finishPage(attempt){const p=state.projects.find(x=>x.id===attempt.projectId);return `<div class="page"><div class="page-title"><p class="eyebrow">CLOSE THE LOOP</p><h1>记录这次复现</h1><p>${esc(p?.title||'')}</p></div><form class="form-card" data-form="finish-reproduction" data-attempt="${attempt.id}"><div class="field-grid"><div class="field full"><label>最终结果</label><select name="successLevel"><option value="success">成功</option><option value="partial">部分完成</option><option value="failed">失败</option></select></div>${field('mainProblem','最大的困难',attempt.mainProblem||'','textarea',true)}${field('missingInfo','缺少什么信息',attempt.missingInfo||'','textarea',true)}${field('misunderstanding','最容易误解的地方',attempt.misunderstanding||'','textarea',true)}${field('suggestion','给原作者的建议',attempt.suggestion||'','textarea',true)}${field('reflection.coreUnderstanding','这个项目最核心的教学目标是什么？',attempt.reflection?.coreUnderstanding||'','textarea',true)}${field('reflection.designReasonUnderstanding','为什么原作者这样设计？',attempt.reflection?.designReasonUnderstanding||'','textarea',true)}${field('reflection.wantedChanges','如果由你使用，最想修改什么？',attempt.reflection?.wantedChanges||'','textarea',true)}${field('reflection.conditionDifferences','你的条件和原作者有什么不同？',attempt.reflection?.conditionDifferences||'','textarea',true)}${field('reflection.aiValue','AI 在项目中真正帮助了什么？',attempt.reflection?.aiValue||'','textarea',true)}</div><div class="form-actions"><a class="button button-secondary" href="#/reproductions/${attempt.id}">← 返回步骤</a><button class="button button-primary">提交复现记录</button></div></form></div>`}

function learnPage(p){const mode=state.ui.mode||'simple';const explain=mode==='simple'?{title:'简单模式：先做出来',text:'你只需要理解：传感器或素材提供输入，项目根据条件做出一个看得见的输出。先遵循步骤，再观察变化。'}:mode==='standard'?{title:'标准模式：尝试一个小修改',text:'可以尝试修改一个参数、一个提示词或一项材料，并在每次修改后记录结果。不要一次修改多个环节。'}:{title:'深入模式：看见项目结构',text:'输入来自设备、图片或资料；核心逻辑对输入做判断；输出是数据、动作或作品。技术细节必须服务教学目标。'};return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">UNDERSTANDING SCAFFOLD</p><h1>理解项目，而不只是完成项目</h1><p>${esc(p.title)}</p></div><div class="mode-switch"><button data-action="mode" data-mode="simple" class="${mode==='simple'?'active':''}">简单模式</button><button data-action="mode" data-mode="standard" class="${mode==='standard'?'active':''}">标准模式</button><button data-action="mode" data-mode="deep" class="${mode==='deep'?'active':''}">深入模式</button></div><section class="panel" style="margin-top:16px"><h2>${explain.title}</h2><p>${explain.text}</p><div class="quick-grid"><div class="quick-item"><p>核心输入</p><strong>${p.hardware?'传感器 / 学生采集的数据':'图片、资料或学生输入'}</strong></div><div class="quick-item"><p>核心输出</p><strong>可观察的结果与学生解释</strong></div><div class="quick-item"><p>关键变量</p><strong>时间、材料、参数或提示词</strong></div><div class="quick-item"><p>关键设备作用</p><strong>${p.hardware?'采集、判断或呈现':'组织、呈现或验证信息'}</strong></div></div></section><section class="panel" style="margin-top:16px"><h2>Understanding Check</h2><p class="form-hint">用于帮助教师自查理解；不评分、不游戏化。</p><form data-form="understanding" data-project="${p.id}"><div class="field-grid">${field('how','这个项目大概怎么工作？','','textarea',true)}${field('important','最重要的三个环节是什么？','','textarea',true)}${field('changeable','哪些内容可以修改？','','textarea',true)}${field('risky','哪些修改风险较高？','','textarea',true)}</div><button class="button button-primary">保存理解检查</button></form></section><section class="panel" style="margin-top:16px"><h2>教师能力路径</h2><div class="quick-grid"><div class="quick-item"><p>Level 1</p><strong>跟随：按步骤完成</strong></div><div class="quick-item"><p>Level 2</p><strong>修改：改参数与提示词</strong></div><div class="quick-item"><p>Level 3</p><strong>判断：验证 AI 输出</strong></div><div class="quick-item"><p>Level 4</p><strong>设计：提出并实现项目</strong></div></div></section></div>`}
function adaptationPage(p){return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">CONDITION ADAPTATION</p><h1>原项目 vs 我的条件</h1><p>系统生成的是有理由的建议，不是自动替换。请由教师判断是否适合真实课堂。</p></div><form class="form-card" data-form="adaptation" data-project="${p.id}"><div class="field-grid">${field('grade','我的年级',p.grade)}${field('subject','我的学科',p.subject,'select',false,SUBJECTS)}${field('lessons','我的可用课时','2 课时')}${field('studentCount','学生人数','30 人')}${field('studentLevel','学生基础','基础不同，需要更多示范')}${field('teacherAbility','教师技术条件','入门')}${field('hardware','我的硬件条件',p.hardware?'暂时没有同型号设备':'有联网电脑')}${field('software','我的软件条件','浏览器和学校允许的软件')}${field('network','网络条件','可稳定联网')}${field('budget','预算','有限')}</div><button class="button button-primary">生成适配方案</button></form></div>`}
function adaptationResultPage(plan){const p=state.projects.find(x=>x.id===plan.projectId);return `<div class="page"><div class="page-title"><p class="eyebrow">ADAPTATION PLAN · RULE-BASED DEMO</p><h1>条件适配方案</h1><p>这是规则化 Mock 建议，不是教育专家验证结论。请结合你的课堂判断。</p></div><section class="comparison"><div class="compare-card"><h3>原项目条件</h3><p>学科：${esc(p.subject)}</p><p>年级：${esc(p.grade)}</p><p>课时：${esc(p.lessons)}</p><p>设备：${esc(p.needs)}</p></div><div class="compare-arrow">→</div><div class="compare-card"><h3>你的条件</h3><p>学科：${esc(plan.profile.subject)}</p><p>年级：${esc(plan.profile.grade)}</p><p>课时：${esc(plan.profile.lessons)}</p><p>硬件：${esc(plan.profile.hardware)}</p></div></section><section class="recommendations">${plan.recommendations.map(r=>`<article class="recommendation"><h3>${esc(r.category)} · ${esc(r.title)}</h3><p><strong>建议：</strong>${esc(r.advice)}</p><p><strong>理由：</strong>${esc(r.reason)}</p><p><strong>影响与风险：</strong>${esc(r.risk)}</p><p><strong>替代方案：</strong>${esc(r.alternative)}</p></article>`).join('')}</section><div class="actions"><button class="button button-secondary" data-action="copy-plan" data-plan="${plan.id}">复制方案</button><button class="button button-secondary" data-action="save-adaptation" data-plan="${plan.id}">保存方案</button><button class="button button-primary" data-action="derivative-project" data-plan="${plan.id}">创建改编项目 →</button></div></div>`}
function makePlan(projectId, profile){const p=state.projects.find(x=>x.id===projectId);const hardwareGap=p.hardware&&/没有|无|暂时没有/.test(profile.hardware);const lessonGap=Number.parseInt(profile.lessons)||0<Number.parseInt(p.lessons)||0;return {id:uid('adapt'),projectId,profile,createdAt:now(),recommendations:[{category:'必须保留',title:'核心学习目标',advice:`保留「${p.goal}」作为学生最终需要解释或完成的任务。`,reason:'这决定项目是否仍然是原教学实践的有效迁移。',risk:'若只保留技术外壳，学科价值会下降。',alternative:'缩小任务范围，而不是删除核心问题。'},{category:'可以修改',title:'任务范围与课时',advice:lessonGap?'将完整任务拆为“教师准备 + 学生验证”两段。':'保留分组任务，并用一个变量作为主要修改点。',reason:'课时和学生基础直接影响课堂节奏。',risk:'压缩过多可能只剩操作，缺少解释。',alternative:'使用样例数据或预制材料。'},{category:hardwareGap?'可以替代':'可以保留',title:'设备与材料',advice:hardwareGap?'使用模拟数据、学校现有设备或低技术材料替代，并补充“模拟与真实测量的差异”讨论。':`优先使用原项目指定的 ${p.needs}。`,reason:'设备是手段，核心学习机制才是迁移判断的基础。',risk:'替代设备可能改变数据精度、交互方式和准备成本。',alternative:'先进行无硬件预演，再安排设备体验。'},{category:'修改风险',title:'不要同时更改多个核心环节',advice:'每次只修改年级、设备、课时或目标中的一项，并记录结果。',reason:'多重变化会让你无法判断哪个调整造成成功或失败。',risk:'复现与迁移问题难以追溯。',alternative:'先保存一个适配草案，再创建改编项目。'}]}}
function aiPackagePage(p){return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">EXTERNAL AI COLLABORATION</p><h1>把要改的问题描述清楚</h1><p>平台不替代 Codex、ChatGPT 或 Claude；它把项目上下文整理成可交给外部 AI 的任务包。</p></div><form class="form-card" data-form="ai-package" data-project="${p.id}"><div class="field-grid">${field('want','我想改什么','','textarea',true)}${field('students','学生是谁','')}${field('goal','新的教学目标','')}${field('conditions','当前条件','','textarea',true)}${field('limits','技术限制','','textarea',true)}${field('mustKeep','不能改变什么','','textarea',true)}${field('output','期望输出','修改建议、可运行代码或课堂材料说明')}</div><button class="button button-primary">生成 AI 任务包</button></form></div>`}
function aiPackageResult(pkg){return `<div class="page"><div class="page-title"><p class="eyebrow">AI TASK PACKAGE · READY FOR REVIEW</p><h1>外部 AI 任务包</h1><p>请检查并复制到你选择的工具。AI 输出回到平台前仍需由教师确认。</p></div><pre class="code-block">${esc(pkg.markdown)}</pre><div class="actions"><button class="button button-primary" data-action="copy-package" data-package="${pkg.id}">复制 Markdown</button><button class="button button-secondary" data-action="download-package" data-package="${pkg.id}">下载 Markdown</button><a class="button button-secondary" href="#/projects/${encodeURIComponent(pkg.slug)}">回到项目</a></div><section class="panel" style="margin-top:18px"><h2>回传结果</h2><p class="form-hint">可记录 GitHub URL、修改说明或资源信息；演示版不执行或解析上传代码。</p><form data-form="ai-return" data-package="${pkg.id}"><div class="field-grid">${field('url','GitHub / 网页 URL','')}${field('summary','修改说明','','textarea',true)}</div><button class="button button-secondary">保存协作记录</button></form></section></div>`}

function transferPage(p){return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">SUBJECT TRANSFER</p><h1>让项目真正成为你的学科教学</h1><p>迁移不是添加一个学科标签；必须说明新学科知识和方法如何改变学生解决问题的方式。</p></div><form class="form-card" data-form="transfer" data-project="${p.id}"><div class="field-grid">${field('subject','目标学科',SUBJECTS.find(s=>s!==p.subject)||'科学','select',false,SUBJECTS)}${field('grade','目标年级',p.grade)}${field('knowledge','目标学科的核心知识','','textarea',true)}${field('method','目标学科的方法','','textarea',true)}${field('lessons','可用课时','2 课时')}${field('studentBase','学生基础','')}</div><button class="button button-primary">生成迁移草案</button></form></div>`}
function transferResult(t){const p=state.projects.find(x=>x.id===t.projectId);return `<div class="page"><div class="page-title"><p class="eyebrow">SUBJECT TRANSFER DRAFT</p><h1>${esc(p.title)} → ${esc(t.profile.subject)}</h1><p>这是待教师审阅的迁移草案，未被标记为教育专家验证。</p></div><section class="panel"><h2>迁移方案</h2><div class="quick-grid"><div class="quick-item"><p>原项目核心机制</p><strong>${esc(t.analysis.mechanism)}</strong></div><div class="quick-item"><p>新学科核心知识</p><strong>${esc(t.profile.knowledge)}</strong></div><div class="quick-item"><p>新的学习任务</p><strong>${esc(t.analysis.task)}</strong></div><div class="quick-item"><p>评价方式</p><strong>${esc(t.analysis.assessment)}</strong></div></div><div class="recommendations"><article class="recommendation"><h3>保留内容</h3><p>${esc(t.analysis.keep)}</p></article><article class="recommendation"><h3>修改 / 新增内容</h3><p>${esc(t.analysis.change)}</p></article><article class="recommendation"><h3>风险</h3><p>${esc(t.analysis.risk)}</p></article></div></section><section class="panel" style="margin-top:18px"><h2>跨学科融合质量检查</h2><div class="quality-grid">${t.quality.map(q=>`<div class="quality-item ${q.pass?'good':'warn'}"><strong>${q.pass?'✓':'!'} ${esc(q.question)}</strong><br>${esc(q.answer)}</div>`).join('')}</div></section><div class="actions"><button class="button button-secondary" data-action="save-transfer" data-transfer="${t.id}">保存迁移草案</button><button class="button button-primary" data-action="transfer-project" data-transfer="${t.id}">创建新项目 →</button></div></div>`}
function makeTransfer(projectId, profile){const p=state.projects.find(x=>x.id===projectId);const knowledge=profile.knowledge||'尚未明确新学科知识';const method=profile.method||'尚未明确新学科方法';const shallow=!profile.knowledge||!profile.method;return {id:uid('transfer'),projectId,profile,createdAt:now(),analysis:{mechanism:`${p.goal}，并通过 ${p.type} 或项目材料得到可观察结果。`,task:`让学生使用 ${profile.subject} 的知识分析、解释或重新设计该结果。`,assessment:'学生能用学科概念解释自己的方案、数据或证据。',keep:`保留原项目中的「${p.goal}」和一项可验证的实践任务。`,change:`新增「${knowledge}」的显性学习任务，并用「${method}」指导学生解决问题。`,risk:'若新学科只作为背景标签，项目仍可能停留在表面跨学科。'},quality:[{question:'新学科是否真实使用本学科知识？',answer:knowledge,pass:!!profile.knowledge},{question:'是否使用了本学科方法？',answer:method,pass:!!profile.method},{question:'是否改变学生解决问题的方式？',answer:profile.method?'学生需要用该方法解释或设计，而不只完成原任务。':'尚未说明。',pass:!!profile.method},{question:'删除新学科后项目是否几乎完全不变？',answer:shallow?'可能是。当前跨学科融合深度较低。':'不应如此；新学科目标已进入任务和评价。',pass:!shallow}]}}
function transferResultPage(transfer){return transferResult(transfer)}
function classroomPage(p){return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">CLASSROOM IMPLEMENTATION</p><h1>今天上完这节课，发生了什么？</h1><p>快速记录真实课堂，再由教师确认结构化经验。不要上传学生身份信息、正脸、完整课堂录像或可识别语音。</p></div><form class="form-card" data-form="classroom" data-project="${p.id}"><div class="callout privacy">学生证据仅可记录匿名作品、匿名学习单或教师整理后的问题。演示版不会上传任何文件。</div><div class="field-grid">${field('classDate','实施日期','','date')}${field('actualLessons','实际课时','')}${field('studentCount','学生人数','')}${field('successLevel','完成情况','success','select',false,['success','partial','failed'])}${field('mainProblem','学生哪里卡了 / 最大问题','','textarea',true)}${field('studentDifficulty','学生最困难的地方','','textarea',true)}${field('changesMade','你改了什么','','textarea',true)}${field('teacherReflection','哪里最好、哪里失败、时间够不够','','textarea',true)}${field('advice','给下一位教师的建议','','textarea',true)}${field('evidence','匿名证据说明（可选）','','textarea',true)}</div><button class="button button-primary">保存课堂反馈</button></form></div>`}
function versionsPage(p){const children=state.relations.filter(r=>r.parentProjectId===p.id).map(r=>({r,child:state.projects.find(x=>x.id===r.childProjectId)})).filter(x=>x.child);return `<div class="page"><a class="text-link" href="#/projects/${encodeURIComponent(p.slug)}">← 返回项目</a><div class="page-title"><p class="eyebrow">PROJECT VERSION NETWORK</p><h1>项目如何被持续改进</h1><p>版本关系记录为什么改、改了什么，以及是否已被真实运行或进入课堂。</p></div><section class="panel"><h2>${esc(p.title)}</h2>${children.length?`<div class="tree"><ul>${children.map(({r,child})=>`<li><strong>${esc(child.title)}</strong> · ${esc(r.relationType)}<br><span class="muted">${esc(r.reason||'未填写修改原因')} · ${VALIDATION[child.validation]||'未验证'} · ${TEACHING_VALIDATION[child.teachingValidation]||'未课堂实施'}</span></li>`).join('')}</ul></div>`:empty('目前没有从该项目创建的改编版本。','<a class="button button-primary" href="#/projects/'+encodeURIComponent(p.slug)+'/adapt">从条件适配开始</a>')}</section></div>`}
function knowledgePage(){const completed=state.attempts.filter(a=>a.status==='completed');const successes=completed.filter(a=>a.successLevel==='success');const classrooms=state.classrooms;const enough=completed.length>=10&&classrooms.length>=4;return `<div class="page"><div class="page-title"><p class="eyebrow">KNOWLEDGE NETWORK</p><h1>来自真实实践的教学知识</h1><p>结论必须有可追溯的项目、复现和课堂证据；不能由模型凭空生成。</p></div><section class="metric-grid"><div class="metric"><strong>${completed.length}</strong><span>完整复现记录</span></div><div class="metric"><strong>${successes.length}</strong><span>成功复现</span></div><div class="metric"><strong>${classrooms.length}</strong><span>课堂实施</span></div><div class="metric"><strong>${state.projects.length}</strong><span>项目总数（含示例）</span></div></section><section class="panel" style="margin-top:18px"><h2>${enough?'待人工审核的洞察':'当前数据不足，暂不能形成可靠结论。'}</h2><p class="muted">${enough?'证据需由人工审核后才能作为教学结论发布。':'需要至少 10 次完成的非作者复现与 4 次课堂实施，且证据可追溯。示例项目和 Mock 数据不作为研究证据。'}</p></section></div>`}
function adminPage(){if(!requireUser('/admin'))return '';if(currentUser().role!=='admin')return `<div class="page">${empty('权限不足。管理员可管理项目、用户和复现记录。')}</div>`;return `<div class="page"><div class="page-title"><p class="eyebrow">ADMIN · LOCAL DEMO</p><h1>基础管理</h1><p>真实服务必须在服务端实施权限、下架、审计与验证状态管理。</p></div><section class="metric-grid"><div class="metric"><strong>${state.projects.length}</strong><span>项目</span></div><div class="metric"><strong>${state.users.length}</strong><span>用户</span></div><div class="metric"><strong>${state.attempts.length}</strong><span>复现</span></div><div class="metric"><strong>${state.classrooms.length}</strong><span>课堂反馈</span></div></section><section class="panel" style="margin-top:18px"><h2>项目状态</h2>${state.projects.map(p=>`<div class="list-row"><div><h3>${esc(p.title)}</h3><p>${esc(p.status)} · ${VALIDATION[p.validation]}</p></div><select data-action="admin-validation" data-project="${p.id}"><option value="unverified" ${p.validation==='unverified'?'selected':''}>尚未验证</option><option value="author_verified" ${p.validation==='author_verified'?'selected':''}>作者已验证</option><option value="others_reproduced" ${p.validation==='others_reproduced'?'selected':''}>他人已复现</option></select></div>`).join('')}</section></div>`}

function render(){header();const r=route().split('?')[0];const parts=r.split('/').filter(Boolean);let html='';if(r==='/')html=homeReworked();else if(r==='/projects')html=projectsPage();else if(r==='/login')html=loginPage();else if(r==='/register')html=loginPage(true);else if(r==='/projects/new')html=newProjectPage();else if(r==='/me/projects')html=myProjects();else if(r==='/me/reproductions')html=reproductionsPage();else if(r==='/knowledge')html=knowledgePage();else if(r==='/admin'||r==='/admin/projects'||r==='/admin/users'||r==='/admin/reproductions')html=adminPage();else if(parts[0]==='reproductions'&&parts[1]){const a=state.attempts.find(x=>x.id===parts[1]);html=a?(parts[2]==='finish'?finishPage(a):reproductionPage(a)):`<div class="page">${empty('找不到该复现记录。')}</div>`}else if(parts[0]==='projects'&&parts[1]){const p=projectBySlug(parts[1]);if(!p)html=`<div class="page">${empty('找不到该项目。','<a class="button button-primary" href="#/projects">回到项目列表</a>')}</div>`;else {const action=parts[2];if(action==='edit')html=newProjectPage(p);else if(action==='reproduce')html=beginAttempt(p.id)||'';else if(action==='learn')html=learnPage(p);else if(action==='adapt')html=adaptationPage(p);else if(action==='adaptation-result'){const x=state.adaptations.find(a=>a.id===parts[3]);html=x?adaptationResultPage(x):empty('找不到适配方案。')}else if(action==='develop-with-ai')html=aiPackagePage(p);else if(action==='ai-package'){const x=state.aiPackages.find(a=>a.id===parts[3]);html=x?aiPackageResult(x):empty('找不到 AI 任务包。')}else if(action==='transfer')html=transferPage(p);else if(action==='transfer-result'){const x=state.transfers.find(a=>a.id===parts[3]);html=x?transferResultPage(x):empty('找不到迁移草案。')}else if(action==='classroom')html=classroomPage(p);else if(action==='versions')html=versionsPage(p);else html=projectDetail(p)}}else html=`<div class="page">${empty('页面不存在。','<a class="button button-primary" href="#/">回到首页</a>')}</div>`;document.getElementById('app').innerHTML=html;document.getElementById('app').focus({preventScroll:true});bindEvents()}

function updateObject(obj,key,value){const parts=key.split('.');if(parts.length===1)obj[key]=value;else{if(!obj[parts[0]])obj[parts[0]]={};obj[parts[0]][parts[1]]=value}}
function formDataObject(form){const result={};for(const [key,val] of new FormData(form).entries())updateObject(result,key,String(val).trim());return result}
function bindEvents(){document.querySelectorAll('[data-go]').forEach(el=>{el.addEventListener('click',()=>go(el.dataset.go));el.addEventListener('keydown',e=>{if(e.key==='Enter')go(el.dataset.go)})});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',event=>handleAction(event,el)));document.querySelectorAll('[data-action="admin-validation"]').forEach(el=>el.addEventListener('change',()=>{const p=state.projects.find(x=>x.id===el.dataset.project);if(p){p.validation=el.value;p.lastVerifiedAt=now().slice(0,10);save();toast('验证状态已更新。')}}));document.querySelectorAll('form[data-form]').forEach(f=>f.addEventListener('submit',event=>handleForm(event,f)))}
function handleAction(event,el){const a=el.dataset.action;if(a==='logout'){state.session=null;save();go('/');toast('已退出演示账户。');return}if(a==='profile'){go('/me/projects');return}if(a==='detail-tab'){state.ui.detailTab=el.dataset.tab;save();render();return}if(a==='start-reproduction'){beginAttempt(el.dataset.project);return}if(a==='wizard-step'){persistDraft();state.wizard.step=Number(el.dataset.step);save();render();return}if(a==='wizard-next'){persistDraft();state.wizard.step=Math.min(10,Number(state.wizard.step||0)+1);save();render();return}if(a==='wizard-prev'){persistDraft();state.wizard.step=Math.max(0,Number(state.wizard.step||0)-1);save();render();return}if(a==='save-draft'){persistDraft();return}if(a==='mock-ai-check'){const d=state.wizard;const info=AIProvider.extractFromText(`${d.title||''} ${d.summary||''} ${d.softwareText||''} ${d.needs||''}`);const notes=[...missingInfo(d),!info.hasVersion?'软件版本':'',d.hardware&&!/型号|model/i.test(d.needs||'')?'硬件具体型号':''].filter(Boolean);toast(notes.length?`Mock AI 建议补充：${notes.join('、')}。教师确认后再保存。`:'Mock AI 未发现基础字段缺失；仍请教师确认内容。');return}if(a==='publish-project'){publishWizard();return}if(a==='edit-project'){const p=state.projects.find(x=>x.id===el.dataset.project);if(p){state.wizard={...p,step:0};save();go('/projects/new')}return}if(a==='archive-project'){const p=state.projects.find(x=>x.id===el.dataset.project);if(p){p.status='archived';p.updatedAt=now();save();render();toast('项目已归档。')}return}if(a==='toggle-check'){const attempt=state.attempts.find(x=>route().includes(x.id));if(attempt){attempt.checklist[el.dataset.key]=el.checked;save()}return}if(a==='step-status'){const attempt=state.attempts.find(x=>route().includes(x.id));if(attempt){const i=Number(el.dataset.index);attempt.stepStates[i].status=el.dataset.status;attempt.currentStep=i;save();render()}return}if(a==='save-issue'){const attempt=state.attempts.find(x=>route().includes(x.id));const input=document.querySelector(`[data-issue-note="${el.dataset.index}"]`);if(attempt&&input){const i=Number(el.dataset.index);attempt.stepStates[i].note=input.value;attempt.issues.push({step:i,description:input.value,type:'other',createdAt:now(),resolved:false});save();toast('卡点已记录。')}return}if(a==='finish-reproduction'){go(`/reproductions/${el.dataset.attempt}/finish`);return}if(a==='mode'){state.ui.mode=el.dataset.mode;save();render();return}if(a==='save-adaptation'){const plan=state.adaptations.find(x=>x.id===el.dataset.plan);if(plan){plan.saved=true;save();toast('适配方案已保存。')}return}if(a==='copy-plan'){const plan=state.adaptations.find(x=>x.id===el.dataset.plan);if(plan)copyText(plan.recommendations.map(r=>`${r.category}｜${r.title}\n建议：${r.advice}\n理由：${r.reason}\n风险：${r.risk}`).join('\n\n'));return}if(a==='derivative-project'){const plan=state.adaptations.find(x=>x.id===el.dataset.plan);if(plan){const p=state.projects.find(x=>x.id===plan.projectId);state.wizard={...p,id:'',title:`${p.title}（适配草案）`,summary:`基于「${p.title}」的条件适配草案。`,sourceType:'adapted',sourceProjectId:p.id,step:0,status:'draft'};save();go('/projects/new');toast('已带入原项目与适配草案，请确认后保存。')}return}if(a==='save-transfer'){const t=state.transfers.find(x=>x.id===el.dataset.transfer);if(t){t.saved=true;save();toast('迁移草案已保存。')}return}if(a==='transfer-project'){const t=state.transfers.find(x=>x.id===el.dataset.transfer);if(t){const p=state.projects.find(x=>x.id===t.projectId);state.wizard={...p,id:'',title:`${p.title}（${t.profile.subject}迁移草案）`,summary:`从「${p.title}」迁移到${t.profile.subject}的项目草案。`,subject:t.profile.subject,sourceType:'adapted',sourceProjectId:p.id,goal:t.analysis.task,step:0,status:'draft'};save();go('/projects/new')}return}if(a==='copy-package'){const pkg=state.aiPackages.find(x=>x.id===el.dataset.package);if(pkg)copyText(pkg.markdown);return}if(a==='download-package'){const pkg=state.aiPackages.find(x=>x.id===el.dataset.package);if(pkg){const blob=new Blob([pkg.markdown],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='ai-task-package.md';link.click();URL.revokeObjectURL(url);toast('已下载任务包。')}return}if(a==='external-link'){showExternalDialog(el.dataset.url);return}}
function copyText(text){navigator.clipboard?.writeText(text).then(()=>toast('已复制到剪贴板。')).catch(()=>toast('无法访问剪贴板，请手动复制。'))}
function showExternalDialog(url){const dialog=document.createElement('dialog');dialog.className='dialog';dialog.innerHTML=`<div class="dialog-content"><button class="dialog-close">×</button><p class="eyebrow">EXTERNAL LINK</p><h1>即将打开外部链接</h1><p>外部资源不属于本平台，请确认来源、版权与内容安全后再继续。</p><div class="actions"><button class="button button-secondary">取消</button><a class="button button-primary" target="_blank" rel="noopener noreferrer" href="${esc(url)}">继续打开</a></div></div>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('.dialog-close').onclick=()=>dialog.remove();dialog.querySelector('.button-secondary').onclick=()=>dialog.remove()}

function handleForm(event, form){event.preventDefault();const type=form.dataset.form;const data=formDataObject(form);if(type==='project-filters'){const qs=new URLSearchParams();for(const [k,v] of Object.entries(data))if(v)qs.set(k,v);if(form.elements.hardware&&form.elements.hardware.checked)qs.set('hardware','1');go(`/projects?${qs}`);return}if(type==='login'){let user=state.users.find(u=>u.email===data.email);if(!user){toast('找不到这个本地账户。可注册一个演示账户。');return}state.session=user.id;save();const next=state.ui.returnTo||'/me/projects';delete state.ui.returnTo;save();go(next);toast(`欢迎回来，${user.name}。`);return}if(type==='register'){if(state.users.some(u=>u.email===data.email)){toast('该邮箱已在本地演示数据中注册。');return}const user={id:uid('user'),name:data.name,email:data.email,role:'user',teamIds:[]};if(data.team){const team={id:uid('team'),name:data.team,memberIds:[user.id]};state.teams.push(team);user.teamIds.push(team.id)}state.users.push(user);state.session=user.id;save();go('/me/projects');toast('演示账户已创建。');return}if(type==='team'){const user=currentUser();const teamName=(data.team||'').trim();if(!user||!teamName){toast('请输入团队名称。');return}let team=state.teams.find(t=>t.name===teamName);if(!team){team={id:uid('team'),name:teamName,memberIds:[]};state.teams.push(team)}if(!team.memberIds.includes(user.id))team.memberIds.push(user.id);if(!user.teamIds.includes(team.id))user.teamIds.push(team.id);save();render();toast(`已加入团队「${team.name}」。`);return}if(type==='finish-reproduction'){const a=state.attempts.find(x=>x.id===form.dataset.attempt);if(!a)return;Object.assign(a,data);a.reflection=data.reflection||{};a.status='completed';a.completedAt=now();save();toast('复现记录已提交。谢谢你如实记录结果。');go(`/projects/${encodeURIComponent(state.projects.find(p=>p.id===a.projectId).slug)}`);return}if(type==='understanding'){const p=state.projects.find(x=>x.id===form.dataset.project);if(p){if(!p.understandingChecks)p.understandingChecks=[];p.understandingChecks.push({userId:(currentUser()||{}).id||'anonymous',...data,createdAt:now()});save();toast('理解检查已保存。')}return}if(type==='adaptation'){const plan=makePlan(form.dataset.project,data);state.adaptations.unshift(plan);save();go(`/projects/${encodeURIComponent(state.projects.find(p=>p.id===plan.projectId).slug)}/adaptation-result/${plan.id}`);return}if(type==='ai-package'){const p=state.projects.find(x=>x.id===form.dataset.project);const markdown=`# 教学项目 AI 协作任务包\n\n## 项目背景\n${p.title}\n${p.summary}\n\n## 教学背景\n原项目面向：${p.grade} ${p.subject}；建议 ${p.lessons}。\n\n## 我想改什么\n${data.want}\n\n## 学生与教学目标\n学生：${data.students}\n目标：${data.goal}\n\n## 当前条件与技术限制\n${data.conditions}\n${data.limits}\n\n## 必须保留\n${data.mustKeep || p.goal}\n\n## 原项目已有资源与设计理由\n资源：${p.assets.map(x=>x.title).join('、')}\n设计理由：${p.decisions.map(x=>x.reason).join('；')}\n\n## 期望输出\n${data.output}\n\n## 验收标准\n1. 保留或明确调整核心教学目标。\n2. 解释每项技术或教学修改的原因和风险。\n3. 不自动处理任何学生个人信息。\n4. 输出供教师审核，不直接发布。`;const pkg={id:uid('aipkg'),projectId:p.id,slug:p.slug,createdAt:now(),input:data,markdown,status:'draft'};state.aiPackages.unshift(pkg);save();go(`/projects/${encodeURIComponent(p.slug)}/ai-package/${pkg.id}`);return}if(type==='ai-return'){const pkg=state.aiPackages.find(x=>x.id===form.dataset.package);if(pkg){pkg.returnResult=data;pkg.status='returned';save();toast('AI 协作回传记录已保存。')}return}if(type==='transfer'){const t=makeTransfer(form.dataset.project,data);state.transfers.unshift(t);save();go(`/projects/${encodeURIComponent(state.projects.find(p=>p.id===t.projectId).slug)}/transfer-result/${t.id}`);return}if(type==='classroom'){const item={id:uid('class'),projectId:form.dataset.project,teacherId:(currentUser()||{}).id||'anonymous',...data,createdAt:now()};state.classrooms.unshift(item);save();toast('课堂反馈已保存。它将作为下一位教师的实践参考。');go(`/projects/${encodeURIComponent(state.projects.find(p=>p.id===item.projectId).slug)}`);return}}

window.addEventListener('hashchange',render);
window.addEventListener('storage',()=>{state=readState();render()});
window.addEventListener('DOMContentLoaded',()=>{if(!location.hash)go('/');else render()});
window.ReproduceClassroom = { resetSeed, state:()=>state };
